def rpn_eval(expr):
    tokens = expr.split()
    stack = []
    ops = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a // b,
    }
    for tok in tokens:
        if tok in ops:
            if len(stack) < 2:
                raise ValueError("malformed expression: too few operands")
            b = stack.pop()
            a = stack.pop()
            if tok == '/' and b == 0:
                raise ZeroDivisionError("division by zero")
            stack.append(ops[tok](a, b))
        else:
            stack.append(int(tok))
    if len(stack) != 1:
        raise ValueError("malformed expression")
    return stack[0]

